44	func newActivationDefs(planID string) activationDefs {
45		return activationDefs{
46			planID:     planID,
47			oldDef:     planDef(planID, 1000, 10, 100, 1000),
48			updatedDef: planDef(planID, 2000, 20, 200, 600),
49			laterDef:   planDef(planID, 3000, 30, 300, 800),
50		}
51	}
