63	// contendActivationWithPlanUpdate 用启动屏障让“开通订阅”与“修改套餐定义”
64	// 真正并发地（而非顺序提交）同时首次提交，返回两项操作各自的错误。
65	func contendActivationWithPlanUpdate(s *Service, acct string, updated Plan) (subErr, updErr error) {
66		start := make(chan struct{})
67		var wg sync.WaitGroup
68		wg.Add(2)
69		go func() {
70			defer wg.Done()
71			<-start
72			subErr = s.Subscribe(acct, updated.ID, utc(2026, 1, 1, 0, 0))
73		}()
74		go func() {
75			defer wg.Done()
76			<-start
77			updErr = s.UpdatePlan(updated)
78		}()
79		close(start)
80		wg.Wait()
81		return subErr, updErr
82	}
