84	// assertActivationSnapshotCoherent 在两项操作争用结束后查询账户：订阅必须
85	// 已生效；当前套餐标识必须仍是该套餐；四项条件必须整份等于原定义或修改后
86	// 定义中的恰好一份（不允许字段级混搭）。返回账户保存的那一份完整快照。
87	func assertActivationSnapshotCoherent(t *testing.T, s *Service, acct string, d activationDefs) PlanTerms {
88		t.Helper()
89		oldTerms, updatedTerms := termsOf(d.oldDef), termsOf(d.updatedDef)
90	
91		st, err := s.Status(acct)
92		if err != nil {
