121	// 有效条件，然后确认账户保存的开通快照原样保留，套餐当前定义则确实已变。
122	func assertLaterPlanUpdateDoesNotRewriteSnapshot(t *testing.T, s *Service, acct string, saved PlanTerms, d activationDefs) {
123		t.Helper()
