211	
212		// 出账后再次查询：账单固定不变；一月用量仍是 25；账户当前条件仍是
213		// 开通保存的那一份。
214		got, err := s.GetBill(acct, jan(2026))
215		if err != nil {
216			t.Fatalf("get bill %q: %v", acct, err)
217		}
218		if got != bill {
