242	// TestConcurrentSubscribeAndPlanUpdateKeepsOneCompleteDefinition 并发提交
243	// “修改套餐定义”与“开通订阅”：每轮两项操作都必须成功；账户保存的条件
244	// 必须整份属于原定义或修改后定义；随后第三次改价、一月 25 单位用量与
245	// 二月一日出账全程沿用该份快照。并发调度不保证某种先后，因此多轮运行，
246	// 并由确定性顺序用例分别锁住两种结果。
247	func TestConcurrentSubscribeAndPlanUpdateKeepsOneCompleteDefinition(t *testing.T) {
248		const rounds = 100
249		sawOld, sawUpdated := false, false
250		for iter := 0; iter < rounds; iter++ {
251			acct := fmt.Sprintf("race-acct-%d", iter)
252			d := newActivationDefs(fmt.Sprintf("race-plan-%d", iter))
253			s, clk := newActivationRaceService(t, acct, d)
254	
255			subErr, updErr := contendActivationWithPlanUpdate(s, acct, d.updatedDef)
256			if subErr != nil {
257				t.Fatalf("iter %d subscribe failed: %v", iter, subErr)
258			}
259			if updErr != nil {
260				t.Fatalf("iter %d plan update failed: %v", iter, updErr)
261			}
262			// 修改总是成功：争用结束后套餐当前定义必为修改后的定义。
263			if got := s.Status2(d.planID); got != d.updatedDef {
264				t.Fatalf("iter %d plan definition = %+v, want updated %+v", iter, got, d.updatedDef)
265			}
266	
267			saved := assertActivationSnapshotCoherent(t, s, acct, d)
268			switch saved {
269			case termsOf(d.oldDef):
270				sawOld = true
271			case termsOf(d.updatedDef):
272				sawUpdated = true
273			}
274	
275			assertLaterPlanUpdateDoesNotRewriteSnapshot(t, s, acct, saved, d)
276			assertJanuaryBillUsesSavedSnapshot(t, s, clk, acct, saved, d)
277		}
278		// 提示性要求：若调度始终只给出一种顺序，确定性用例仍会分别保障两种结果。
279		if !sawOld || !sawUpdated {
280			t.Logf("scheduler only exercised one order this run (old=%v updated=%v); deterministic subtests cover both",
281				sawOld, sawUpdated)
282		}
283	}
284	
285	// TestSubscribeAndPlanUpdateBothOrdersDeterministic 以确定顺序锁住两种先后
286	// 关系：开通先被接受时账户保存原定义（一月账单 2750）；修改先被接受时
287	// 账户保存修改后的定义（一月账单 3180）。两种顺序下第三组定义都不能混入。
288	func TestSubscribeAndPlanUpdateBothOrdersDeterministic(t *testing.T) {
289		t.Run("subscribe-accepted-first-keeps-old-definition", func(t *testing.T) {
290			acct := "det-sub-first"
291			d := newActivationDefs("det-sub-first-plan")
292			s, clk := newActivationRaceService(t, acct, d)
293	
294			// 顺序一：开通先被接受，账户当场保存原定义。
295			if err := s.Subscribe(acct, d.planID, utc(2026, 1, 1, 0, 0)); err != nil {
296				t.Fatalf("subscribe: %v", err)
297			}
298			st, _ := s.Status(acct)
299			if !st.Subscribed || st.CurrentTerms != termsOf(d.oldDef) {
300				t.Fatalf("after subscribe: %+v, want old terms", st)
301			}
302			// 修改随后被接受：只影响之后新快照，已开通订阅不被改写。
303			if err := s.UpdatePlan(d.updatedDef); err != nil {
304				t.Fatalf("update: %v", err)
305			}
306			saved := assertActivationSnapshotCoherent(t, s, acct, d)
307			if saved != termsOf(d.oldDef) {
308				t.Fatalf("subscribe-first must keep old definition, got %+v", saved)
309			}
310	
311			assertLaterPlanUpdateDoesNotRewriteSnapshot(t, s, acct, saved, d)
312			assertJanuaryBillUsesSavedSnapshot(t, s, clk, acct, saved, d)
313		})
314	
315		t.Run("update-accepted-first-keeps-updated-definition", func(t *testing.T) {
316			acct := "det-upd-first"
317			d := newActivationDefs("det-upd-first-plan")
318			s, clk := newActivationRaceService(t, acct, d)
319	
320			// 顺序二：修改先被接受，套餐定义已换成新值。
321			if err := s.UpdatePlan(d.updatedDef); err != nil {
322				t.Fatalf("update: %v", err)
323			}
324			if got := s.Status2(d.planID); got != d.updatedDef {
325				t.Fatalf("plan definition = %+v, want updated", got)
326			}
327			// 开通随后被接受：必须按修改后的完整定义保存快照。
328			if err := s.Subscribe(acct, d.planID, utc(2026, 1, 1, 0, 0)); err != nil {
329				t.Fatalf("subscribe: %v", err)
330			}
331			saved := assertActivationSnapshotCoherent(t, s, acct, d)
332			if saved != termsOf(d.updatedDef) {
333				t.Fatalf("update-first must keep updated definition, got %+v", saved)
334			}
335	
336			assertLaterPlanUpdateDoesNotRewriteSnapshot(t, s, acct, saved, d)
337			assertJanuaryBillUsesSavedSnapshot(t, s, clk, acct, saved, d)
338		})
