516		// 之后以同一标识提交合法付款，得到首次成功登记的结果。
517		r, err := s.RecordPayment("a", "p1", jan(2026), 400)
518		if err != nil || !r.Registered || r.BillBalance != 600 || r.Settled {
519			t.Fatalf("first success after failed attempt: %+v %v", r, err)
