522			t.Fatalf("bill paid after failed+success: %d", b.Paid)
523		}
524		// 重报返回历史结果。
525		r2, err := s.RecordPayment("a", "p1", jan(2026), 400)
526		if err != nil || r2.Registered || r2.BillBalance != 600 || r2.Settled {
527			t.Fatalf("replay: %+v %v", r2, err)
528		}
