337			if b.Terms.PlanID != want.plan || b.TotalDue != want.fee {
338				t.Fatalf("bill %s changed: %+v", want.p, b)
339			}
340		}
341	}
342	
343	func mustBill(t *testing.T, s *Service, acct string, p Month) Bill {
344		t.Helper()
345		b, err := s.CreateBill(acct, p)
346		if err != nil {
347			t.Fatalf("create bill %s: %v", p, err)
348		}
349		return b
350	}
351	
352	func TestPlanChangeWhileSuspended(t *testing.T) {
353		s, clk := newTestService(utc(2026, 1, 20, 12, 0))
354		mustPlan(t, s, planDef("a", 1000, 0, 0, 0))
355		mustPlan(t, s, planDef("b", 2000, 0, 0, 0))
356		mustAccount(t, s, "u")
357		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
358		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "e", At: utc(2026, 1, 10, 0, 0), Quantity: 1}); err != nil {
359			t.Fatal(err)
360		}
361		clk.t = utc(2026, 2, 1, 0, 0)
362		if _, err := s.CreateBill("u", jan(2026)); err != nil {
363			t.Fatal(err)
364		}
365		clk.t = utc(2026, 2, 8, 0, 0)
366		st, _ := s.Status("u")
367		if !st.Suspended {
368			t.Fatal("should be suspended")
369		}
370	
371		// 停用期间允许安排与取消，但不清除欠费、不解除停用。
372		mustSchedule(t, s, "u", "b")
373		st, _ = s.Status("u")
374		if !st.Suspended || st.PendingChange == nil || st.PendingChange.TargetPlanID != "b" {
375			t.Fatalf("schedule while suspended: %+v", st)
376		}
377		if err := s.CancelPlanChange("u"); err != nil {
378			t.Fatalf("cancel while suspended: %v", err)
379		}
380		st, _ = s.Status("u")
381		if !st.Suspended || st.PendingChange != nil {
382			t.Fatalf("cancel while suspended changed state: %+v", st)
383		}
384	
385		// 停用期间安排的切换在月初生效，但停用状态按原规则仍由欠费决定。
386		mustSchedule(t, s, "u", "b")
387		clk.t = utc(2026, 3, 1, 0, 0)
388		st, _ = s.Status("u")
389		if !st.Suspended || st.CurrentTerms.PlanID != "b" {
390			t.Fatalf("suspended switch: %+v", st)
391		}
392		// 结清后恢复，规则不变。
393		if _, err := s.RecordPayment("u", "p1", jan(2026), 1000); err != nil {
394			t.Fatal(err)
395		}
396		st, _ = s.Status("u")
397		if st.Suspended {
398			t.Fatalf("still suspended after payment: %+v", st)
399		}
400	}
401	
402	func TestConcurrentPlanChangesAndBilling(t *testing.T) {
403		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
404		mustPlan(t, s, planDef("a", 1000, 5, 10, 0))
405		mustPlan(t, s, planDef("b", 2000, 5, 20, 0))
406		mustAccount(t, s, "u")
407		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
408		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "e", At: utc(2026, 1, 10, 0, 0), Quantity: 8}); err != nil {
409			t.Fatal(err)
410		}
411	
412		const n = 64
413		var wg sync.WaitGroup
414		wg.Add(n * 3)
415		for i := 0; i < n; i++ {
416			go func(i int) {
417				defer wg.Done()
418				_, _ = s.SchedulePlanChange("u", "b")
419			}(i)
420			go func() {
421				defer wg.Done()
422				_ = s.CancelPlanChange("u")
423			}()
424			go func(i int) {
425				defer wg.Done()
426				// 1 月未出账时并发的不同事件：要么计入 1 月、要么因出账被拒，结果自洽。
427				_, _ = s.RecordEvent(Event{
428					AccountID: "u",
429					EventID:   fmt.Sprintf("c%d", i),
430					At:        utc(2026, 1, 12, 0, 0),
431					Quantity:  1,
432				})
433			}(i)
434		}
435		wg.Wait()
436	
437		// 无论上述操作如何交错，最终状态必须内部一致。
438		st, _ := s.Status("u")
439		if st.CurrentTerms.PlanID != "a" {
440			t.Fatalf("current plan = %s, want a", st.CurrentTerms.PlanID)
441		}
442	
443		// 推进到 2 月并并发出账：1 月账单必须恰好使用一个套餐的条件。
444		clk.t = utc(2026, 2, 1, 0, 0)
445		bills := make([]Bill, n)
446		wg.Add(n)
447		for i := 0; i < n; i++ {
448			go func(i int) {
449				defer wg.Done()
450				b, err := s.CreateBill("u", jan(2026))
451				if err != nil {
452					t.Errorf("concurrent bill: %v", err)
453					return
454				}
455				bills[i] = b
456			}(i)
457		}
458		wg.Wait()
459		var first Bill
460		for i, b := range bills {
461			if i == 0 {
462				first = b
463				continue
464			}
465			if b != first {
466				t.Fatalf("bills differ:\n%+v\n%+v", first, b)
467			}
468		}
469		if first.Terms.PlanID != "a" {
470			t.Fatalf("jan bill terms = %s", first.Terms.PlanID)
471		}
472		// 内部金额自洽：月费 1000、额度 5、单价 10。
473		wantOverage := first.TotalUsage - 5
474		if wantOverage < 0 {
475			wantOverage = 0
476		}
477		if first.OverageUnits != wantOverage || first.MonthlyFee != 1000 ||
478			first.OverageFee != wantOverage*10 || first.TotalDue != 1000+wantOverage*10 {
479			t.Fatalf("jan bill inconsistent: %+v", first)
480		}
481	}
